<?php
declare(strict_types=1);
require_once __DIR__.'/../classes/GreenPortalDatabase.php';require_once __DIR__.'/../classes/QuestionnaireService.php';require_once __DIR__.'/../classes/TaskService.php';require_once __DIR__.'/../classes/WorkflowService.php';
$env=GreenPortalDatabase::env();$u=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');$t=GreenPortalDatabase::connect($env,'gmodelo_dbp','GPT');$code='TEST_SUPPLIER_P2_'.date('YmdHis').'_'.random_int(100,999);$qid=0;$vid=0;$pid=0;$pub=0;$exec=0;$workflow=0;$result=['status'=>'ERRO','codigo'=>$code];
try{$q=$u->prepare("INSERT INTO amb_questionario(codigo,nome_pt,modulo,criado_por) VALUES (:codigo,'Teste fornecedor P2','SUPPLIER',1)");$q->execute(['codigo'=>$code]);$qid=(int)$u->lastInsertId();$q=$u->prepare("INSERT INTO amb_questionario_versao(codquestionario,versao,status,percentual_minimo,criado_por) VALUES (:qid,1,'PUBLICADA',80,1)");$q->execute(['qid'=>$qid]);$vid=(int)$u->lastInsertId();$q=$u->prepare("INSERT INTO amb_questionario_pergunta(codversao,codigo,texto_pt,tipo,obrigatoria,ordem) VALUES (:vid,'APROVA','Fornecedor aprovado?','SIM_NAO',1,1)");$q->execute(['vid'=>$vid]);$pid=(int)$u->lastInsertId();$q=$u->prepare("INSERT INTO amb_questionario_opcao(codpergunta,codigo,rotulo_pt,valor,pontuacao,ordem) VALUES (:pid,'SIM','Sim','SIM',1,1)");$q->execute(['pid'=>$pid]);$q=$u->prepare("INSERT INTO amb_questionario_publicacao(codversao,codigo_publicacao,publicado_por) VALUES (:vid,:pub,1)");$q->execute(['vid'=>$vid,'pub'=>'Q:'.$code.':V:1']);$pub=(int)$u->lastInsertId();$service=new QuestionnaireService($t,$u);$started=$service->start($code,1,null,'fo_fornecedores','999','TEST-SUPPLIER-'.$code,'SUPPLIER_QUESTIONNAIRE');$exec=(int)$started['codexecucao'];$submitted=$service->submit($exec,1,['APROVA'=>'SIM']);$q=$t->prepare("SELECT i.codinstancia FROM workflow_instancias i JOIN workflow_definicoes d ON d.codworkflow=i.codworkflow WHERE d.codigo='SUPPLIER_QUESTIONNAIRE' AND i.origem_id=:origem ORDER BY i.codinstancia DESC LIMIT 1");$q->execute(['origem'=>(string)$exec]);$workflow=(int)$q->fetchColumn();if($workflow<=0)throw new RuntimeException('Workflow do fornecedor não foi iniciado.');$wf=new WorkflowService($t,new TaskService($t));$wf->transition($workflow,'APROVAR',1,'Homologação funcional P2');$state=$t->prepare('SELECT status,etapa_atual FROM workflow_instancias WHERE codinstancia=:id');$state->execute(['id'=>$workflow]);$state=$state->fetch(PDO::FETCH_ASSOC);$result=['status'=>'CONCLUIDA','execucao'=>$exec,'resultado'=>$submitted,'workflow'=>$workflow,'workflow_status'=>$state['status']??null,'workflow_etapa'=>$state['etapa_atual']??null];}
finally{if($workflow>0){$t->prepare('DELETE FROM workflow_historico WHERE codinstancia=:id')->execute(['id'=>$workflow]);$t->prepare('DELETE FROM workflow_instancias WHERE codinstancia=:id')->execute(['id'=>$workflow]);}if($exec>0){$t->prepare('DELETE FROM amb_questionario_resultados WHERE codexecucao=:id')->execute(['id'=>$exec]);$t->prepare('DELETE FROM amb_questionario_respostas WHERE codexecucao=:id')->execute(['id'=>$exec]);$t->prepare('DELETE FROM amb_questionario_execucoes WHERE codexecucao=:id')->execute(['id'=>$exec]);}if($pub>0)$u->prepare('DELETE FROM amb_questionario_publicacao WHERE codpublicacao=:id')->execute(['id'=>$pub]);if($pid>0){$u->prepare('DELETE FROM amb_questionario_opcao WHERE codpergunta=:id')->execute(['id'=>$pid]);$u->prepare('DELETE FROM amb_questionario_pergunta WHERE codpergunta=:id')->execute(['id'=>$pid]);}if($vid>0)$u->prepare('DELETE FROM amb_questionario_versao WHERE codversao=:id')->execute(['id'=>$vid]);if($qid>0)$u->prepare('DELETE FROM amb_questionario WHERE codquestionario=:id')->execute(['id'=>$qid]);echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;}
